argv:
set timeout 30
spawn env QWEN_TUI_RENDERER=opentui QWEN_CODE_SKIP_UPDATE_CHECK_ONCE=true bun packages/cli/dist/index.js
expect { -re {ready} {} -re {unexpected critical error|Error:} { exit 1 } timeout { exit 2 } }
send -- "ZXQ"
expect { -re {ZXQ} {} timeout { exit 3 } }
send -- "\177\r"
expect { -re {❯.*ZX} {} -re {unexpected critical error|Error:} { exit 4 } timeout { exit 5 } }
send -- "\003"
expect { eof {} timeout { exit 6 } }
